def is_simply_connected(squares):
    if not squares:
        return True
    start = next(iter(squares))
    visited = {start}
    queue = collections.deque([start])
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in squares and (nx, ny) not in visited:
                visited.add((nx, ny))
