    search_min_y = min_y - 1
    search_max_y = max_y + 1

    all_squares = set()
    for x in range(search_min_x, search_max_x + 1):
        for y in range(search_min_y, search_max_y + 1):
            all_squares.add((x, y))

    not_in_squares = all_squares - squares

    reachable = set()
    queue = collections.deque()

    for x in range(search_min_x, search_max_x + 1):
        for y in range(search_min_y, search_max_y + 1):
            if x == search_min_x or x == search_max_x or y == search_min_y or y == search_max_y:
                if (x, y) not in squares:
                    reachable.add((x, y))
                    queue.append((x, y))

    while queue:
        x, y = queue.popleft()
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in not_in_squares and (nx, ny) not in reachable:
                reachable.add((nx, ny))
                queue.append((nx, ny))

    return not_in_squares.issubset(reachable)

