    visited = {start_node}
    stack = [start_node]
    while stack:
        curr = stack.pop()
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nb = (curr[0] + dx, curr[1] + dy)
            if nb in squares and nb not in visited:
                visited.add(nb)
                stack.append(nb)
    return len(visited)

